"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[6273],{6273:function(a){a.exports=JSON.parse('{"name":"Patrick Goodwin","menu":{"home":"Balay","about":"Mahitungod Kanako","portfolio":"Portfolio","projects":"Mga Proyekto sa Website","tiger":"Pinulongan sa Tigre","portfolio_translator":"Portfolio Translator","formatter":"JSON & YAML Formatter","contact":"Kontaka Ako"},"home":{"title":"Senior Full-Stack Engineer | Produkto ug Sistema","animated":{"first":"Senior Full-Stack Engineer","second":"Sistema ug Architecture Builder","third":"SaaS Product Engineer","fourth":"Kasaligang Software, Mga Resulta sa Negosyo"},"footer":"Ang website karon gihubad ug magamit sa 100+ ka mga pinulongan!","descriptionA":"Ang senior full-stack engineer nga adunay 6+ ka tuig nga kasinatian sa pagkuha sa mga produkto gikan sa dili klaro nga mga kinahanglanon hangtod sa kasaligan nga mga sistema sa produksiyon. Gidisenyo nako ang arkitektura luyo sa React, Angular, .NET, Node.js, Java, C#, Go, ug SQL nga mga aplikasyon: tin-aw nga mga utlanan sa serbisyo, lig-on nga mga modelo sa datos, luwas nga mga pattern sa pag-access, ug ang mga tim sa mga agianan sa pagpadala mahimong molihok nga adunay pagsalig.","descriptionB":"Ang akong trabaho nagkonektar sa mga desisyon sa engineering ngadto sa mga resulta sa negosyo. Gikan sa usa ka construction-estimating SaaS nga naghimo sa spreadsheet data ngadto sa kliyente-ready proposals ngadto sa revenue-generating web platforms, nagtukod ko og software sa palibot sa workflow, risgo, ug masukod nga bili nga importante sa mga tawo nga naggamit niini.","portfolio_button":"Akong Portfolio","contact_button":"Kontaka Ako","about_button":"Mahitungod Kanako"},"about":{"title":"Mahitungod Kanako","personal_summary":{"title":"Personal nga Sumaryo","text":"Usa ako ka senior full-stack engineer nga nakabase sa Orlando, FL nga tag-iya ang agianan gikan sa problema sa produkto hangtod sa sangputanan sa produksiyon. Naghimo ako og mga pagpili sa teknolohiya sa pagserbisyo sa sistema: .NET ug Entity Framework Core kung ang usa ka lig-on nga pagkahan-ay nga domain ug masulayan nga pagpadayon nga butang; Angular o React kung komplikado ang mga workflow nanginahanglan usa ka mapadayon nga interface; Node.js o Go kung ang usa ka API, integration, o high-performance nga himan nanginahanglan usa ka naka-focus nga runtime. Sa mga produkto sa SaaS, internal nga mga workflow, ug mga platform nga nag-atubang sa kustomer, nanguna ko nga adunay klaro nga mga tradeoff, luwas ug lig-on nga disenyo, awtomatiko nga pagsulay, ug mga gawi sa paghatud nga tabangi ang mga team nga ipadala ang bililhon nga software nga dili biyaan ang utang sa operasyon."},"professional_experience":{"title":"Propesyonal nga Kasinatian","entries":[{"jobtitle":"Senior Software Engineer","where":"Disenyo Interactive","date":"2025 - Karon"},{"jobtitle":"Software Engineer","where":"Orion180 nga Seguro","date":"2024 - 2025"},{"jobtitle":"Software Engineer","where":"SupremeMC","date":"2020 - 2024"},{"jobtitle":"Software Engineer","where":"Paspas nga Pagkat-on","date":"2023"},{"jobtitle":"Nanguna nga Software Engineer (Programa sa Estudyante)","where":"Clemson University GDI Program","date":"2021 - 2022"},{"jobtitle":"Desk Supervisor","where":"Unibersidad sa Clemson","date":"2021 - 2022"}]},"technical_skills":{"title":"Mga Kahanas sa Teknikal","header1":"Mga Pinulongan sa Programming","header2":"Frameworks & Libraries","header3":"Mga Himan ug Teknolohiya"},"services":{"title":"Akong Serbisyo","entries":[{"title":"Full Stack Engineering","text":"Nanguna ko sa end-to-end nga paghatud sa produkto: paghubad sa mga workflow sa negosyo ngadto sa mga utlanan sa sistema, mga modelo sa datos, mga API, ug mga interface, dayon pagdala sa trabaho pinaagi sa pagsulay, pag-deploy, ug pag-uli. Ang tumong mao ang software nga ang usa ka team mahimong mag-evolve ug mag-operate, dili usa ka koleksyon sa mga dili konektado nga mga screen."},{"title":"Arkitektura sa Produkto ug Platform","text":"Gipili nako ang mga plataporma ug mga pattern base sa problema: layered .NET services para sa business domains, component-driven Angular o React applications para sa komplikadong operasyon, relational mga modelo sa datos alang sa may tulubagon nga mga workflow, ug mga integrasyon nga gidesinyo uban sa mga paagi sa kapakyasan, pagkontrol sa pag-access, ug pagmintinar sa hunahuna."},{"title":"Andam nga Paghatud sa Produksyon","text":"Nagtukod ako uban ang mga katinuoran pagkahuman sa paglansad sa pagtan-aw: ang mga sekreto nga gitago nga dili kontrolado sa gigikanan, klaro nga mga agianan sa pagbalhin sa database, pagtugot nga gibase sa papel, pag-validate sa mga utlanan sa sistema, automated nga mga pagsulay, kahibalo sa CI/CD, ug praktikal nga obserbasyon. Kini ang mga detalye nga naghimo sa usa ka prototype nga mahimong kasaligan nga software."}]}},"portfolio":{"title":"Portfolio","filter_by":"Filter Portfolio Ni:","entries":{"biblioteca":{"title":"Biblioteca JSON","text":"Usa ka Python-based localization pipeline nga naghimo sa usa ka structured content source ngadto sa globally accessible portfolio. Nagdumala kini sa datos sa paghubad isip usa ka sistema nga mamentinar kay sa mano-mano nga pagkopya sa panid nga kopya, nga nagtugot sa site sa pagsukod sa 100+ ka mga pinulongan ug paghimo sa tibuok kalibutan nga pagkab-ot sa usa ka kapabilidad sa operasyon imbes nga usa ka higayon nga bahin.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Ikonektar ang Upat","text":"Daghang pamilya nga adunay kapin sa 50+ nga pagpatuman sa dula nga Connect Four. Kini nga proyekto naglakip sa mga pagpatuman sa kapin sa 30 ka lain-laing mga programming language, lakip ang Java, C++, Python, JavaScript, ug uban pa. Dugang pa, naglakip usab kini sa kapin sa 20+ ka lain-laing mga frameworks o ubang mga format, lakip ang React.js, Ruby on Rails, ASP.NET, ug uban pa.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"Grocery App","text":"Usa ka full-stack .NET 9 Blazor Server nga aplikasyon nga nagpakita sa tinuyo nga backend nga arkitektura alang sa usa ka negosyo nga workflow. Ang controller/service/repository split nagtipig sa mga lagda sa aplikasyon, data access, ug presentasyon nga independente nga masulayan; Ang Entity Framework Core naghatag ug lig-on nga pagpadayon; ug ang Ang komprehensibo nga test suite nanalipod sa pamatasan samtang nag-uswag ang produkto.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Interop nga Proyekto","text":"Usa ka cross-language interoperability reference nga naglangkob sa 15 programming language ug 18 execution patterns. Gisusi sa proyekto ang utlanan diin ang mga sistema kanunay nga mahimong huyang: mga kontrata sa proseso, pagbayloay sa datos, pamatasan sa runtime, ug balik-balik nga mga agianan sa panagsama. Gipakita niini ang mga sistema sa panghunahuna nga gikinahanglan kung ang usa ka produkto mas dako kaysa usa ka stack.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Rehistro sa Imbentaryo","text":"Usa ka full-stack nga POS ug imbentaryo nga workflow nga gitukod uban ang Angular 17+ ug Node.js. Gi-modelo niini ang mga kabalaka sa operasyon sa usa ka sistema sa B2B: gipamatud-an nga mga tiggamit, kontrol sa pag-access nga gibase sa papel, katukma sa imbentaryo, ug usa ka pagbiaybiay nga dagan sa pagbayad. Ang proyekto gidisenyo sa palibot sa aktuwal nga trabaho nga gihimo sa usa ka rehistro nga team, dili lang usa ka katalogo sa mga bahin sa balangkas.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"JSON & YAML Auto Formatter","text":"Usa ka browser-based nga JSON ug YAML validation ug formatting tool nga gitukod sa Go ug gihugpong sa WebAssembly. Ang pagbalhin sa parsing engine ngadto sa WASM mopadayon sa interaksyon nga responsive ug lokal sa browser samtang nag-aplay ug tinuod nga parser aron makuha ang dili balido nga input. Kini usa ka gipunting nga panig-ingnan sa pagpili sa usa ka runtime nga arkitektura alang sa pasundayag, kadali, ug pagsalig sa gumagamit.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Pag-takeoff nga Engine","text":"Usa ka pagtukod nga nagbanabana sa SaaS nga gitukod sa palibot sa usa ka mahal, dali nga sayup nga daloy sa trabaho sa kontraktor. Ang React + Express nga produkto nag-ingest sa CSV ug Excel nga datos, nag-mapa sa dili managsama nga mga kolum ngadto sa usa ka magamit nga modelo sa domain, nagkalkula sa trench excavation ug earthwork volume, nagsubay sa labor ug markup, ug naghimo sa andam nga kliyente nga PDF ug mga sugyot sa Pulong. Kini mao ang bug-os nga product lifecycle engineering: data parsing, kalkulasyon lagda, usa ka gipasinaw operator workflow, ug deliverables nga makatabang sa usa ka negosyo pagbalhin gikan sa hilaw nga inputs ngadto sa usa ka bid.","link":"https://takeoffengine.com"},"minecraft_json_generator":{"title":"Minecraft JSON Generator","text":"Ang gaan nga JSON generator nga gitukod sa Python alang sa Minecraft nga kapanguhaan ug mga pakete sa datos. Kini nga proyekto gigamit sa pagmugna og JSON nga mga file para sa Minecraft mods, lakip na ang custom nga mga butang, block, ug entity. Mapuslanon kaayo alang sa dili lamang paghimo og mga custom datapacks, apan alang sa mods usab pinaagi sa mod name switching feature.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"Akong Edukasyon nga Kasinatian","text":"Uban sa akong personal nga mga proyekto, nakakuha usab ako daghang mga kahanas gikan sa kasinatian sa edukasyon. I-klik dinhi aron makita ang akong LinkedIn nga profile alang sa dugang nga impormasyon.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"Akong Propesyonal nga Kasinatian","text":"Unom ka tuig nga kasinatian sa propesyonal nga inhenyero sa tibuuk nga mga team sa produkto, platform sa negosyo, ug software nga nag-atubang sa kustomer. Ang akong trabaho naglakip sa pagtukod sa mapadayon nga mga layer sa aplikasyon, pagtinabangay sa tibuuk nga mga disiplina sa paghatud, ug paghimo og mga teknikal nga desisyon sa siklo sa kinabuhi sa produkto, operasyon. risgo, ug long-term nga pagpanag-iya sa panglantaw.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Patrick Goodwin Portfolio Website","text":"Usa ka portfolio sa React nga naghunahuna sa produksiyon nga nagtagad sa pagka-access ug pag-abot sa tibuuk kalibutan ingon mga kinahanglanon sa engineering. Naglakip kini sa usa ka mapadayon nga pipeline sa paghubad alang sa 100+ ka mga pinulongan, mga interactive nga himan nga gipaluyohan sa WebAssembly, responsive ug accessible nga mga pattern sa UI, ug usa ka arkitektura sa proyekto gidisenyo nga motubo samtang ang bag-ong trabaho gipadala.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Patrick\'s Lua Script Library","text":"Usa ka mapuslanon nga librarya sa mga script sa Lua alang sa umaabot nga pakisayran. Kini nga librarya gigamit sa pag-automate sa mga buluhaton sa Lua scripts, nga mahimong magamit alang sa performance-kinahanglan nga mga buluhaton, tungod kay ang Lua kasagaran usa ka mas paspas nga scripting nga pinulongan kay sa Python ug Ruby.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Ang Microsoft Excel Spreadsheet Scripts (VBA) ni Patrick","text":"Usa ka mapuslanon nga librarya sa mga script sa VBA alang sa Microsoft Excel. Kini nga librarya gigamit sa pag-automate sa mga buluhaton sa mga spreadsheet sa Excel.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Ang Neovim Config ni Patrick","text":"Ang akong personal nga Neovim configuration. Kini nga proyekto gigamit sa pag-configure sa Neovim sa akong gusto, lakip na ang custom keybindings, tema, ug mga plugins. Kini nga proyekto gigamit sa paghimo sa Neovim nga mas user-friendly ug episyente alang sa akong personal nga paggamit.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Patrick\'s Mapa Generator","text":"Usa ka himan sa pagtaho sa geospatial sa Python nga gihimo gamit ang GeoPandas ug Matplotlib aron makamugna og mga mapa sa county ug estado sa US. Gihimo niini ang geograpikanhong datos nga mahimong mabasa nga mga artifact sa pagtuki, nga nagpakita sa usa ka data pipeline mindset: pagpili sa husto nga domain library, pag-normalize sa mga input, ug paghimo og mga output nga pagsuporta sa klaro nga mga desisyon.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Patrick\'s PowerShell Script Library","text":"Usa ka mapuslanon nga librarya sa mga PowerShell script para sa umaabot nga reperensiya. Mapuslanon sa $profile script nga bahin, akong nakita nga kini dako kaayo nga makatabang sa pag-automate sa mga buluhaton gikan sa Windows terminal, tungod kay ako usa ka kanunay nga tiggamit sa Windows OS.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Patrick\'s Ruby Script Library","text":"Usa ka mapuslanon nga librarya sa Ruby scripts alang sa umaabot nga pakisayran. Mapuslanon alang sa umaabot nga Ruby on Rails nga mga konsepto sa pag-uswag.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"PDF Skills Builder","text":"Usa ka dokumento-generation workflow nga gitukod uban sa Python, Pdfkit, Jinja2, HTML, ug structured JSON data. Gibulag niini ang magamit pag-usab nga datos gikan sa mga template sa presentasyon aron makamugna ang gipaangay nga mga resume sa PDF nga makanunayon, usa ka praktikal nga sumbanan alang sa pagkunhod sa manual nga trabaho ug paghimo sa mga dokumento sa negosyo masubli.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Proyekto sa Pag-encrypt sa Rijandel","text":"Usa ka comparative set sa 10+ Rijndael nga pagpatuman sa 128-, 192-, ug 256-bit nga mga variant. Ang pag-implementar pag-usab sa usa ka algorithm nga sensitibo sa seguridad sa tibuok mga pinulongan usa ka disiplinado nga ehersisyo sa eksaktong mga espesipikasyon, masulayan nga kinaiya, ug ang mga limitasyon sa lebel sa pinulongan nga madala, tanan nga mapuslanon nga mga instinct para sa mga sistema nga nagdumala sa sensitibo nga datos.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"SupremeMC Minecraft Mod","text":"Usa ka Minecraft Mod nga nagdugang custom nga mga himan, armor, mob, block, dimensyon, ug daghan pa nga mga bahin sa dula. Gitukod uban sa Java nga bersyon 8-17 alang sa pinili nga Minecraft nga mga bersyon tali sa 1.16 ug 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"Pinulongan sa Pagprograma sa Tigre","text":"Usa ka naandan nga programming language ug interpreter nga gitukod sa Go to explore language runtime design, execution behavior, ug performance tradeoffs. Ang pag-compile niini sa WebAssembly ug ang pag-integrate niini ngadto sa portfolio nagmugna og usa ka tinuod, inspeksyon nga nawong sa produkto alang sa mga sistema sa lebel sa engineering kay sa pagbiya sa trabaho isip usa ka eksperimento lamang sa repositoryo.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Website sa Tiger Tailgating Pros","text":"Usa ka website sa React nga gihatag alang sa usa ka negosyo sa Clemson, SC tailgating. Gihubad sa trabaho ang pagtanyag sa gamay nga negosyo sa usa ka tin-aw nga panaw sa kustomer ug kasaligan nga presensya sa web, pagpadapat sa panghunahuna sa produkto aron matabangan ang usa ka tinuud nga organisasyon nga magbag-o sa interes sa mga pangutana ug kita.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Proyekto sa Turing Machine","text":"Pamilya sa kapin sa 30+ ka mga pagpatuman sa Turing Machine. Gigamit aron ipakita ang pagkakompleto sa turing alang sa lain-laing mga programming language alang sa panukiduki, ilabi na alang sa Tiger Programming Language.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"Pinulongan sa Pagprograma sa Tigre"},"contact":{"title":"Kontaka Ako","header":"Impormasyon sa Kontak","email":"pattygsocials@gmail.com","description":"Motubag ko sa mga pangutana gikan sa email ug LinkedIn nga mga mensahe. Motawag usab ako og balik kung ang akong numero gihatag pinaagi sa resume o kung dili, bisan kung gusto nako nga itago ang akong numero sa telepono nga pribado."},"formatter":{"title":"JSON & YAML Linter","description":"Usa ka himan sa kalidad sa datos nga nakabase sa browser nga nag-validate ug nag-format sa JSON ug YAML gamit ang Go engine nga giipon sa WebAssembly. Ang arkitektura nagpadayon sa pag-parse duol sa tiggamit alang sa paspas, pribado nga feedback samtang gipatuman ang tinuod nga mga lagda sa syntax sa utlanan sa datos. Kini usa ka compact nga pananglitan sa pagdesinyo sa usa ka kasaligan nga dagan sa trabaho sa developer sa palibot sa katukma, pasundayag, ug pagsalig.","more_info1":"Para sa dugang nga impormasyon, tan-awa ang README sa","more_info2":"JSON/YAML Formatter Repository.","format_as":"Format Ingon:","auto_detect":"Auto Detect","format":"Lint ug Format","valid_json":"\u2713 Balido nga JSON","valid_yaml":"\u2713 Balido nga YAML","invalid_json":"Dili balido nga JSON","invalid_yaml":"Dili balido nga YAML","empty_input":"Palihug isulod ang pipila ka JSON o YAML aron lint.","too_large":"Dagko kaayo ang input (max 1MB gitugot).","fixed_yaml_spacing":"\u26a0 Ang YAML adunay dili balido nga gilay-on/indentasyon apan awtomatik nga giayo ug giporma.","loading":"Nagkarga sa tig-format...","waiting_for_input":"Naghulat alang sa input...","load_failed":"Dili ma-load ang formatter.","output":"Output:","input_code":"Input","json_examples":"Mga Ehemplo sa JSON","yaml_examples":"Mga Ehemplo sa YAML"},"tiger":{"title":"Pinulongan sa Tigre","description":"Ang Tiger usa ka naandan nga programming language ug Go interpreter nga gihimo aron ma-explore ang runtime nga arkitektura, semantika sa lengguwahe, ug mga tradeoff sa pasundayag. Ang pag-compile sa interpreter sa WebAssembly nagpalihok nga ang mga sistema molihok sa usa ka interactive, produkto nga nakabase sa browser: ang mga tiggamit mahimo\u2019g magpatuman sa mga programa direkta samtang ang runtime nagpabilin nga madaladala. ug nahimulag gikan sa aplikasyon sa host.","more_info1":"Para sa dugang nga impormasyon, tan-awa ang README sa","more_info2":"GitHub Repository sa Pagprograma sa Tigre.","select_engine":"Pilia ang Engine:","tiger_code":"Kodigo sa tigre:","run_tiger":"Dagan Tigre","output":"Output:"},"tab":{"title":"Patrick Goodwin","description":"Ang senior full-stack engineer nga adunay 6+ ka tuig nga kasinatian sa pagdesinyo sa mga produkto sa SaaS, mga sistema sa produksiyon, ug software nga makamugna og kita."},"copy":{"text":"Kopyaha","copied":"Gikopya!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"Sunda ko"},"languages":{"title":"Portfolio Translator","description":"Hibal-i kung giunsa ang akong portfolio ma-access sa mga bisita gikan sa tibuuk kalibutan nga adunay suporta alang sa kapin sa 100 ka mga pinulongan.","global_accessibility":{"title":"Global Accessibility","description":"Ang akong porfolio anaa sa kapin sa {count} nga mga pinulongan, nga naghimo niini nga ma-access sa mga bisita gikan sa tibuok kalibutan. Kini nga multilingguwal nga pamaagi nagpakita sa akong pasalig sa inclusivity ug global nga pagkab-ot sa software development.","stats":{"languages_supported":"Mga Pinulongan nga Gisuportahan","countries_represented":"Mga Nasud nga Representante","continents_covered":"Mga Kontinente nga Sakop"}},"features":{"title":"Mga bahin","items":[{"title":"Tinuod nga Panahon nga Paghubad:","description":"Pagbalhin dayon sa mga pinulongan gamit ang tigpili sa pinulongan"},{"title":"Pinulongan nga gibase sa URL:","description":"Ang mga gusto sa pinulongan gipreserbar sa URL"},{"title":"Suporta sa Lumad nga Script:","description":"Tukma nga paghubad sa mga script sama sa Arabic, Chinese, Hindi, ug uban pa"},{"title":"Pagkasensitibo sa Kultura:","description":"Gikonsiderar sa mga hubad ang konteksto sa kultura, dili lang literal nga mga kahulugan"},{"title":"Gi-optimize sa SEO:","description":"Ang matag variant sa pinulongan gi-optimize alang sa mga search engine"}]},"world_map":{"title":"Interactive nga Mapa sa Kalibutan","description":"Pag-hover sa mga nasud sa mapa aron makita ang ilang gisuportahan nga mga pinulongan:","languages_label":"Mga pinulongan","legend":{"supported":"Mga Pinulongan nga Gisuportahan","not_supported":"Walay Suporta sa Pinulongan"},"zoom_controls":{"zoom_in":"Pag-zoom In","zoom_out":"Pag-zoom Out","reset":"I-reset ang Panglantaw"}},"supported_languages":{"title":"Gisuportahan nga mga Pinulongan"},"interactive_country_map":{"title":"Interactive nga Mapa sa Nasud","description":"Pag-hover sa mga nasud sa ubos aron makita ang ilang gisuportahan nga mga pinulongan:","language_count":{"single":"pinulongan","multiple":"mga pinulongan"}},"tooltips":{"no_language_support":"Walay suporta sa pinulongan"}},"logotext":"PATRICK"}')}}]);